      try {
        const {data,error} = await client.from("apps").select("*").order("created_at",{ascending:false});
        if (error) throw error;
        apps = data || [];
        popularityCache = null;
        popularityRequest = null;
        renderApps();
        loadNotifications(client);
      } catch (error) {
        console.error("Gagal memuat apps:",error);
        document.getElementById("appGrid").innerHTML = `
Daftar APK belum dapat dimuat. Periksa koneksi atau pengaturan Supabase.`;
        document.getElementById("homeApps").innerHTML = `
Konten belum dapat dimuat. Silakan coba lagi.`;
